pub proof fn combiner_request_ids_not_contains(combiners: Map<NodeId, CombinerState>, rid: ReqId)
    requires
        combiners.dom().finite(),
    ensures
        combiner_request_id_fresh(combiners, rid) <==> !combiner_request_ids(combiners).contains(
