fn readonly_ready_to_read_inductive(pre: Self, post: Self, rid: ReqId, node_id: NodeId) {
}

#[inductive(readonly_apply)]
fn readonly_apply_inductive(pre: Self, post: Self, rid: ReqId) {
    assert forall |id| #[trigger] post.local_reads.contains_key(id)
        implies post.read_results_match(post.local_reads[id]) by {
        if id != rid {
            assert(post.local_reads[id] == pre.local_reads[id]);
            assert(pre.read_results_match(pre.local_reads[id]));
        } else {
            assert(post.local_reads[id].is_Done());
            let read = post.local_reads[id];
            match read {
                ReadonlyState::Done { ret, version_upper_bound, node_id, op } => {
                    assert(post.replicas[node_id] == compute_nrstate_at_version(post.log, post.current_local_version(node_id)));
                    assert(post.current_local_version(node_id) >= version_upper_bound);
                    assert(post.version_upper_bound >= version_upper_bound);
                    assert(ret == DT::dispatch_spec(compute_nrstate_at_version(post.log, version_upper_bound), op));
                    assert(exists |v: nat| rangeincl(version_upper_bound, v, post.version_upper_bound)
                        && ret == DT::dispatch_spec(compute_nrstate_at_version(post.log, v), op));
                }
                _ => {}
            }
        }
    }
}

